 30	  let total = 0;
 31	  for await (const chunk of chunks) {
 32	    total += chunk.length;
 33	    if (total > MAX_BYTES) throw readError(name, 'too large');
 34	    parts.push(chunk);
 35	  }
 36	  return Buffer.concat(parts, total);
 37	}
 38	
 39	async function* fileChunks(handle) {
 40	  const buffer = Buffer.alloc(65536);
 41	  for (;;) {
 42	    const { bytesRead } = await handle.read(buffer, 0, buffer.length, null);
 43	    if (bytesRead === 0) return;
 44	    yield Buffer.from(buffer.subarray(0, bytesRead));
 45	  }
 46	}
 47	
 48	async function isDirectory(path) {
 49	  try {
 50	    return (await stat(path)).isDirectory();
 51	  } catch {
 52	    return false;
 53	  }
 54	}
 55	
 56	async function readFile(path) {
 57	  let handle;
 58	  try {
 59	    handle = await open(path, 'r');
 60	  } catch (err) {
 61	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
 62	    if (err.code === 'EISDIR' || (await isDirectory(path))) throw readError(path, 'is a directory');
 63	    throw readError(path, 'cannot read');
 64	  }
 65	  try {
 66	    if ((await handle.stat()).isDirectory()) throw readError(path, 'is a directory');
 67	    return await collect(fileChunks(handle), path);
 68	  } catch (err) {
 69	    if (err instanceof CliError) throw err;
 70	    throw readError(path, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
 71	  } finally {
 72	    // The data is already read; a failed close of a read-only handle changes nothing.
 73	    await handle.close().catch(() => {});
 74	  }
 75	}
 76	
 77	async function readStdin() {
 78	  try {
 79	    // A directory stream ends without data or error, so reject it up front.
 80	    if (fstatSync(0).isDirectory()) throw readError('stdin', 'cannot read');
 81	    return await collect(process.stdin, 'stdin');
 82	  } catch (err) {
 83	    if (err instanceof CliError) throw err;
 84	    throw readError('stdin', 'cannot read');
 85	  } finally {
 86	    process.stdin.destroy();
 87	  }
 88	}
 89	
 90	function depthExceeds(value, limit) {
 91	  const stack = [[value, 0]];
 92	  while (stack.length > 0) {
 93	    const [current, depth] = stack.pop();
 94	    if (current === null || typeof current !== 'object') continue;
 95	    if (depth + 1 > limit) return true;
 96	    for (const item of Object.values(current)) stack.push([item, depth + 1]);
 97	  }
 98	  return false;
 99	}
100	
101	async function loadJson(arg) {
102	  const name = arg === STDIN ? 'stdin' : arg;
103	  const bytes = arg === STDIN ? await readStdin() : await readFile(arg);
104	  let text;
105	  try {
106	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
107	  } catch {
108	    throw dataError(name, 'invalid UTF-8');
109	  }
110	  let value;
111	  try {
112	    value = JSON.parse(text);
113	  } catch {
114	    throw dataError(name, 'invalid JSON');
115	  }
116	  if (depthExceeds(value, MAX_DEPTH)) throw dataError(name, 'too deep');
117	  return value;
118	}
119	
120	// Same text as JSON.stringify(value, null, 2) for JSON values, built without recursion so
121	// that results made deep by a patch (repeated `copy`) cannot overflow the call stack.
122	function stringify(value) {
123	  const parts = [];
124	  const stack = [{ value, indent: '' }];
125	  while (stack.length > 0) {
126	    const item = stack.pop();
127	    if (typeof item === 'string') {
128	      parts.push(item);
129	      continue;
130	    }
131	    const { value: current, indent } = item;
132	    const keys = current !== null && typeof current === 'object' ? Object.keys(current) : null;
133	    if (keys === null) {
134	      parts.push(JSON.stringify(current));
135	      continue;
136	    }
137	    const isArray = Array.isArray(current);
138	    if (keys.length === 0) {
139	      parts.push(isArray ? '[]' : '{}');
140	      continue;
141	    }
142	    const inner = `${indent}  `;
143	    parts.push(isArray ? '[' : '{');
144	    stack.push(`\n${indent}${isArray ? ']' : '}'}`);
145	    for (let i = keys.length - 1; i >= 0; i--) {
146	      stack.push({ value: current[keys[i]], indent: inner });
147	      const label = isArray ? '' : `${JSON.stringify(keys[i])}: `;
148	      stack.push(`${i === 0 ? '' : ','}\n${inner}${label}`);
149	    }
150	  }
151	  return parts.join('');
152	}
153	
154	async function main(args) {
155	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
156	  const [patchArg, docArg = STDIN] = args;
157	  if (patchArg === STDIN && docArg === STDIN) throw new CliError(USAGE, 2);
158	  const patch = await loadJson(patchArg);
159	  const doc = await loadJson(docArg);
160	  let result;
161	  try {
162	    result = applyPatch(doc, patch);
163	  } catch (err) {
164	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
165	    throw err;
166	  }
167	  process.stdout.write(`${stringify(result)}\n`);
168	}
169	
170	// A reader that closes the pipe early (EPIPE) ends the run quietly; other write errors get one line.
171	process.stdout.on('error', (err) => {
172	  if (err.code !== 'EPIPE') process.stderr.write('Error: cannot write output\n');
173	  process.exit(1);
174	});
175	
176	main(process.argv.slice(2)).catch((err) => {
177	  process.stderr.write(err instanceof CliError ? `${err.message}\n` : 'Error: unexpected failure\n');
178	  process.exitCode = err instanceof CliError ? err.exitCode : 1;
179	});

